import{_ as o,C as t,o as r,c as i,a6 as d,E as n,j as a,a as c}from"./chunks/framework.CKIbuWFA.js";const g=JSON.parse('{"title":"Revise estatísticas entre datas","description":"","frontmatter":{"title":"Revise estatísticas entre datas","docId":"user.points.statistics","translationKey":"user.points.statistics","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"a7333d75baa9aec6e0c4afb69d1c773575a56ee8da982f0fa5a11a73b903ec2d","translationRevision":"7c3770e4190c05abb3a91210f4474d18a8f26b6dc5e9ba104cb60cca8a635f0e","order":20},"headers":[],"relativePath":"pt/user/points/statistics.md","filePath":"pt/user/points/statistics.md","lastUpdated":1794611623000}'),l={name:"pt/user/points/statistics.md"};function p(u,e,m,h,v,f){const s=t("DemoFrame");return r(),i("div",null,[e[0]||(e[0]=d('<h1 id="review-statistics-across-dates" tabindex="-1">Revise estatísticas entre datas <a class="header-anchor" href="#review-statistics-across-dates" aria-label="Permalink to &quot;Revise estatísticas entre datas {#review-statistics-across-dates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Compare a atividade de um criador em um intervalo de datas útil e entenda por que os totais diferem do feed visível ou do saldo de pontos. Você precisa de atividade registrada na instalação local e do criador desejado selecionado por <a href="./../live/connections.html">Connections</a>. O login no Cloud não é a origem dessas análises locais.</p><h2 id="query-the-recorded-period" tabindex="-1">Consulte o período registrado <a class="header-anchor" href="#query-the-recorded-period" aria-label="Permalink to &quot;Consulte o período registrado {#query-the-recorded-period}&quot;">​</a></h2><ol><li>Abra <strong>Analytics</strong> e confirme o criador exibido ao lado dos controles de data. O criador selecionado determina quais agregados armazenados são consultados.</li><li>Escolha <strong>Today</strong>, <code>7d</code>, <code>30d</code>, <code>90d</code> ou um intervalo personalizado. Para datas personalizadas, defina início e fim explicitamente e confira sua ordem.</li><li>Leia o intervalo exibido e a contagem de sessões antes de comparar resultados. Os limites de datas locais usam um deslocamento de fuso horário; mudar o fuso do computador pode alterar a interpretação de um período.</li><li>Selecione a métrica necessária: chats, presentes, curtidas, diamantes ou pico de espectadores. Use os gráficos de atividade para comparar períodos e a tabela de contribuidores para inspecionar os principais espectadores retornados.</li><li>Pesquise na tabela de contribuidores um espectador já presente nos dados retornados. Não é uma pesquisa irrestrita de todos os espectadores já observados.</li><li>Selecione <strong>Refresh</strong> após nova atividade ou ao retornar à página. Registre criador, datas e métrica junto de qualquer número compartilhado.</li></ol><p>A página atual chama a operação nativa <code>analytics.summary</code> com um criador e intervalo de datas. Ela lê agregados persistidos, incluindo sessões registradas anteriormente; não se limita aos eventos ainda mantidos no feed atual. O banco de análises armazena agregados, não uma transcrição do chat.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Análises locais persistidas e consultas por intervalo de datas estão disponíveis. Datas vazias legitimamente não retornam atividade. Saldos de pontos podem diferir porque <a href="./rules.html">taxas de ganho</a>, ajustes manuais e atribuições de automação expressam uma medida diferente. Diamantes, contagens de presentes e pontos não são unidades intercambiáveis.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Se os dados parecerem ausentes, limpe a pesquisa de contribuidores, amplie o intervalo de datas, confirme o criador e atualize. Após um erro do host, guarde seu código de diagnóstico e tente novamente quando a conexão se recuperar. Limpar o feed não apaga as análises. Um diretório de dados novo não tem histórico anterior; use <a href="./../preferences/backups.html">backups</a> ao mover instalações.</p>',10)),n(s,{scenario:"analytics",locale:"pt",title:"Demonstração: análises"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[c("Detalhes de operação "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Detalhes de operação {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"O Analytics solicita atualmente 10 principais contribuidores para o criador e período escolhidos. A busca filtra esse subconjunto, sem pesquisar todos os espectadores. Esses agregados persistidos têm período e unidade diferentes dos rankings de diamantes/likes da sessão e dos saldos de pontos. Preserve criador, datas e métrica ao exportar ou comparar.",-1))])}const q=o(l,[["render",p]]);export{g as __pageData,q as default};
